<?php defined('ABSPATH')||exit;get_header();?><main id="main-content" class="section shell"><header class="page-header"><p class="eyebrow">Morgenbrot Journal</p><h1><?php single_post_title();?></h1></header><div class="post-grid"><?php if(have_posts()):while(have_posts()):the_post();?><article <?php post_class('card post-card');?>><a class="card-media post-card-media" href="<?php the_permalink();?>" aria-label="<?php echo esc_attr(get_the_title().' lesen');?>"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large',['alt'=>get_the_title()]);else morgenbrot_placeholder('news');?></a><div class="card-body"><time datetime="<?php echo esc_attr(get_the_date('c'));?>"><?php echo esc_html(get_the_date());?></time><h2><a href="<?php the_permalink();?>"><?php the_title();?></a></h2><?php the_excerpt();?><a class="text-link" href="<?php the_permalink();?>">Weiterlesen →</a></div></article><?php endwhile;the_posts_pagination();else:?><div class="empty"><h2>Noch keine Neuigkeiten</h2><p>Beiträge können im WordPress-Adminbereich veröffentlicht werden.</p></div><?php endif;?></div></main><?php get_footer();
